export type CommerceContextValue = CommerceSnapshot & {
  ready: boolean;
  busy: string | null;
  mode: "mock" | CommerceAdapter["mode"];
  provider?: CommerceProviderIdentity;
  error: CommerceError | null;
  persistenceError: "read" | "write" | "invalid" | null;
  canWrite: boolean;
